void velocityVerletStep2(vec3& vel, const vec3& force, double mass, double dt) {
    vec3 acceleration;
    acceleration.x = force.x / mass;
    acceleration.y = force.y / mass;
    acceleration.z = force.z / mass;

    vel.x += acceleration.x * (dt / 2.0);
    vel.y += acceleration.y * (dt / 2.0);
    vel.z += acceleration.z * (dt / 2.0);
}

void velocityVerletStep2(vec3& vel, const vec3& force, double mass, double dt) {
    vec3 acceleration = force.operator/(mass);
    vel = vel.operator+(acceleration.operator*(dt / 2.0));
}

void velocityVerletStep2(vec3& vel, const vec3& force, double mass, double dt) {
    double half_dt = dt / 2.0;
    vel.x += (force.x / mass) * half_dt;
    vel.y += (force.y / mass) * half_dt;
    vel.z += (force.z / mass) * half_dt;
}

